  $t = [System.IO.File]::ReadAllText($f.FullName)
  foreach ($m in [regex]::Matches($t, '(?:const\s+string|const\s+String|String|string)\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*"([^"]+)"')) {
    $n=$m.Groups[1].Value; $v=$m.Groups[2].Value
    if ($gmap.ContainsKey($n)) { if ($gmap[$n] -ne $v) { $null=$gdup.Add($n) } } else { $gmap[$n]=$v }
  }
}
$rows = @()
foreach ($f in $files) {
  $t = [System.IO.File]::ReadAllText($f.FullName)
  if ($t -notmatch 'HasPermission') { continue }
  $lmap = @{}
