  $i = 0
  while ($true) {
    $i = $t.IndexOf('HasPermission', $i); if ($i -lt 0) { break }
    $p = $t.IndexOf('(', $i + 13); if ($p -lt 0) { break }
    if ($t.Substring($i, $p - $i) -notmatch 'HasPermission\s*$') { $i = $p; continue }
    $depth = 0; $k = $p
    while ($k -lt $t.Length) { if ($t[$k] -eq '(') { $depth++ } elseif ($t[$k] -eq ')') { $depth--; if ($depth -eq 0) { break } }; $k++ }
    $arg = $t.Substring($p, $k - $p + 1)
    $lineStart = $t.LastIndexOf("`n", $i); $line = ($t.Substring(0, $i) -split "`n").Count
    $lineText = ($t -split "`n")[$line-1].Trim()
    $isComment = $lineText.StartsWith('//')
    $ids = @()
    foreach ($q in [regex]::Matches($arg, '"([^"]+)"')) { $ids += $q.Groups[1].Value }
    foreach ($c in [regex]::Matches($arg, '\b([A-Z][A-Z0-9_]{3,})\b')) {
      $n = $c.Groups[1].Value
      if ($lmap.ContainsKey($n)) { $ids += $lmap[$n] } elseif ($gmap.ContainsKey($n) -and -not $gdup.Contains($n)) { $ids += $gmap[$n] }
    }
    foreach ($id in ($ids | Sort-Object -Unique)) {
      $rows += [pscustomobject]@{ P=$id; OK=($dbPerm.Contains($id) -or $dbGroup.Contains($id)); F=$f.FullName.Substring($root.Length+1); L=$line; Cmt=$isComment }
    }
    $i = $k
  }
}
