    $s = $code.IndexOf('(', $p); if ($s -lt 0) { continue }
    $rest = $code.Substring($s+1)
    $e = $rest.IndexOfAny(@(',', ')'))
    if ($e -lt 0) { continue }
    $firstArg = $rest.Substring(0, $e).Trim()
