$ws='g:\0.DỰ ÁN\Z.WEB-CDN-QUYNHON'
$root = Join-Path $ws '1.WEB -CTT'
foreach ($rel in @('Controls\CRM\Portfo\List.ascx.cs','Controls\CRM\Portfo\Edit.ascx.cs','Controls\CRM\SendInfo\List.ascx.cs','Controls\CRM\SendInfo\Edit.ascx.cs','Controls\CRM\Support\List.ascx.cs','Controls\CRM\Support\Edit.ascx.cs','Controls\Sims\ExamMarkEdit.ascx.cs')) {
