$ws='g:\0.DỰ ÁN\Z.WEB-CDN-QUYNHON'
$dataFile = Join-Path $ws '3.SQL\06.10.2026\data - bảng liên quan quyền.sql'
$raw = [System.IO.File]::ReadAllText($dataFile)
$root = Join-Path $ws '1.WEB -CTT'
$files = Get-ChildItem $root -Recurse -Include *.cs -File | Where-Object { $_.FullName -notmatch '\\(obj|bin)\\' }
$rows = @()
foreach ($f in $files) {
  $lines = [System.IO.File]::ReadAllLines($f.FullName)
  $map = @{}
  foreach ($m in [regex]::Matches(($lines -join "`n"), '(?:const\s+string|const\s+String|String|string)\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*"([^"]+)"')) { $map[$m.Groups[1].Value] = $m.Groups[2].Value }
  for ($i=0; $i -lt $lines.Count; $i++) {
    $full = $lines[$i]
    $code = ($full -replace '//.*$','')
    $m = [regex]::Match($code, 'HasPermission[A-Za-z_]*\s*\(')
    if (-not $m.Success) { continue }
    $s = $code.IndexOf('(', $m.Index)
    $rest = $code.Substring($s+1)
    $e = $rest.IndexOfAny(@(',', ')')); if ($e -lt 0) { continue }
    $firstArg = $rest.Substring(0, $e).Trim()
    $id = $null
    $q = [regex]::Match($firstArg, '"([^"]+)"'); if ($q.Success) { $id = $q.Groups[1].Value }
    elseif ($map.ContainsKey($firstArg)) { $id = $map[$firstArg] }
    if ($id -eq $null) { continue }
    $rows += [pscustomobject]@{ P=$id; OK=$raw.Contains("N'$id'"); F=$f.FullName.Substring($root.Length+1); L=($i+1); Cmt=($full.Trim().StartsWith('//')) }
  }
}
$live = $rows | Where-Object { -not $_.Cmt }
$miss = $live | Where-Object { -not $_.OK }
Write-Output '===== QUYEN DANG CHAY (dong code that) MA FILE DATA CHUA CO ====='
$miss | Sort-Object P,F,L | Format-Table -AutoSize | Out-String -Width 200
Write-Output ('Luot quyen dang chay: ' + $live.Count + ' | luot thieu: ' + $miss.Count)
Write-Output '--- ID thieu (unique) ---'
($miss | Select-Object -Expand P -Unique | Sort-Object) -join "`n"
Write-Output '--- ID da co trong data (unique) ---'
($live | Where-Object {$_.OK} | Select-Object -Expand P -Unique | Sort-Object) -join "`n"
$rows | Export-Csv -NoTypeInformation -LiteralPath (Join-Path $ws '3.SQL\06.10.2026\_perm_audit.csv') -Encoding UTF8
Write-Output '(da xuat chi tiet: 3.SQL\06.10.2026\_perm_audit.csv)'
